T(24, "24-4", "The Rules of the Den", "Narrative", [
"By Saturday morning, the den beneath Yusuf\u2019s apple tree was finally finished. It had taken three weekends, two balls of string and a great deal of arguing, but the walls of old pallets stood firm, and a blue tarpaulin stretched across the top like a roof. Yusuf\u2019s best friends, Poppy and Tomasz, stepped back to admire it.",
"\u201cRight,\u201d said Poppy, producing a crumpled sheet of paper from her pocket. \u201cEvery proper den needs rules. Rule one: members only. Rule two: nobody enters without the password. Rule three: no little brothers or sisters.\u201d She glanced pointedly towards the house, where Yusuf\u2019s sister Zara was watching through the kitchen window.",
"Yusuf felt his face grow warm. \u201cZara is only six,\u201d he muttered. \u201cShe has been helping me carry things all month.\u201d \u201cThat is exactly the problem,\u201d said Poppy. \u201cShe will touch everything and tell the whole street our password.\u201d Tomasz shuffled his feet and studied the grass, clearly wishing that he were somewhere else.",
"\u201cIt is my garden,\u201d said Yusuf. \u201cIt was my idea,\u201d said Poppy. For several minutes neither of them would give way, and the silence between them grew as heavy as the clouds gathering above the apple tree.",
"The first drops of rain settled the argument, though not in the way anyone expected. Within seconds the wind had whipped the tarpaulin free at one corner, and it flapped wildly, threatening to tear the whole roof away. The three friends grabbed at it, but the rope kept slipping through their cold, wet fingers.",
"Then Zara appeared, wearing her wellingtons and a raincoat two sizes too big. Without a word, she scrambled underneath, took the rope from Yusuf and looped it round a pallet in a neat, tight knot. \u201cOur Beavers leader showed me,\u201d she said. \u201cIt is called a clove hitch, and it never comes undone.\u201d She tied the other three corners in exactly the same way, and the tarpaulin stopped flapping.",
"Crouched inside the dry, dim den, listening to the rain drumming on the roof, Poppy glanced at her crumpled list. Slowly, she took a pencil, crossed out the third rule and scribbled something new underneath. \u201cRule three,\u201d she read aloud, a little sheepishly. \u201cAnyone who can tie a proper knot is welcome.\u201d Zara beamed so widely that Yusuf could not help grinning too.",
], [
 dict(d="2b",k="mc",m=1,q="What was stretched across the top of the den like a roof?",opts=["A wooden board","A blue tarpaulin","A garden umbrella","A large blanket"],a="B"),
 dict(d="2b",k="short",m=1,q="What was Poppy\u2019s third rule?",a="No little brothers or sisters.",g="Accept any answer that says younger brothers and sisters were not allowed."),
 dict(d="2a",k="find",m=1,q="Find and copy one word from paragraph 1 that shows the walls of the den were solid.",a="firm",g="Accept \u201cfirm\u201d only."),
 dict(d="2d",k="short",m=1,q="Why do you think Yusuf\u2019s face grew warm when Poppy read out her third rule?",a="He was upset or embarrassed because the rule meant his sister could not join.",g="Accept angry, upset, embarrassed or cross, linked to Zara being left out. Do not accept \u201che was hot\u201d."),
 dict(d="2d",k="short",m=1,q="Why do you think Tomasz \u201cstudied the grass\u201d during the argument?",a="He did not want to take sides / he felt uncomfortable.",g="Accept any answer showing he felt awkward or wanted to avoid the argument."),
 dict(d="2a",k="mc",m=1,q="In paragraph 7, what does the word \u201csheepishly\u201d mean?",opts=["Loudly and proudly","Very quickly","In a slightly embarrassed way","Without any interest"],a="C"),
 dict(d="2c",k="order",m=1,q="Number the events from 1 to 4 to show the order they happened in the story.",items=["Zara tied the corners of the tarpaulin.","Poppy read out her rules.","Poppy crossed out the third rule.","The wind pulled the tarpaulin loose."],a=[3,1,4,2],g=Q2),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each sentence.",items=["The den took three weekends to build.","Yusuf\u2019s sister Zara is six years old.","Zara learned to tie knots from her teacher at school.","Poppy wrote the rules on a sheet of paper."],a=["T","T","F","T"],g=TF),
 dict(d="2g",k="short",m=1,q="The writer says the silence \u201cgrew as heavy as the clouds\u201d. What does this suggest about the argument?",a="The tension was building and the atmosphere was uncomfortable, like a storm about to break.",g="Accept any answer about growing tension or an uncomfortable atmosphere."),
 dict(d="2d",k="short",m=1,q="How do you know that Poppy changed her mind about Zara? Give one piece of evidence.",a="She crossed out the third rule and wrote a new one that welcomed anyone who could tie a knot.",g="Accept any answer that mentions crossing out or rewriting the rule."),
 dict(d="2c",k="mc",m=1,q="Which sentence best sums up the story?",opts=["A little girl helped to solve an argument by showing what she could do.","Three friends lost their den in a storm.","Yusuf built a den all by himself.","Poppy wanted to move the den to a new garden."],a="A"),
 dict(d="2e",k="short",m=1,q="Zara asks if she can come to the den again next weekend. What do you think Poppy will say? Give a reason.",a="She will say yes, because Zara proved herself and Poppy has changed the rule.",g="Accept any sensible prediction supported by what happened in the story."),
])
